mapper.update:
CREATE TABLE IF NOT EXISTS product_property_${productId} ( device_id STRING TAG, report_time TIMESTAMP FIELD
, "${column.name}" ${column.type} FIELD
)

mapper.insert:
INSERT INTO product_property_${productId} (time, device_id

    , report_time


    , "${column.name}"

)
VALUES (#{ts}, #{deviceId}

    , #{reportTime}


    , #{column.value}

)

mapper.select:
SELECT "${columnName}" AS "value", time AS update_time
FROM product_property_${productId}
WHERE device_id = #{deviceId}
  AND time >= #{startTime}
  AND time <= #{endTime}
  AND "${columnName}" IS NOT NULL
ORDER BY time DESC
